SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, COUNT(*) AS event_count, CAST(COUNT(*) filter (WHERE l.valueuom = 'mg' AND l.value BETWEEN 0 AND 100) AS FLOAT) / NULLIF(COUNT(*), 0) AS troponin_percentage, AVG(l.value) AS average_troponin, MEDIAN(l.value) AS median_troponin, (percentile_cont(0.75) within GROUP (ORDER BY l.value) - percentile_cont(0.25) within GROUP (ORDER BY l.value)) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 41 AND 51 AND d.icd_code IN ('4234', '4235') AND l.valueuom = 'mg' AND l.value BETWEEN 0 AND 100 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code ORDER BY event_count DESC NULLS LAST;